// Cross-cutting TILE-SCAFFOLD contract over the real generators (T4, R3).
//
// Complements:
//   - the per-plugin PIN tests (AlphabetOrderWorksheet.test.ts /
//     SentenceBuildingWorksheet.test.ts pin the exact `tileBlanks` /
//     `tileWords` values row by row, generated by scripts/generate-pins.ts);
//   - framework/PrintableSheet.test.tsx (renders the WriteBox blanks and
//     WordTileRun for fixture problems);
//   - framework/visuals-sheets.test.ts (the picture-cue contract).
//
// Pinned invariants here:
//   1. BANDING — write-box blanks (letters) and word tiles (sentence)
//      exist ONLY in the early cue band (isEarlyCueBand = word tier 2..4
//      = Years 1..3). Prep and Years 4..6 print zero tile metadata: their
//      markup is the legacy plain underlines / parenthesised word lists.
//   2. EXACT COUNTS — how many rows of each sheet carry tiles is
//      deterministic and pinned (re-pin only on a deliberate bank/shape
//      change).
//   3. ONE BOX PER BLANK — every letters write-box row's prompt carries
//      exactly one "__" (the box IS the answer slot; no hybrid rows).
//   4. NO ANSWER LEAKAGE (sentence) — the tile bank is the SHOWN
//      (scrambled) order: it is a permutation of the answer's word
//      multiset but is NEVER the answer order itself, and early-band
//      prompts no longer print that bank as text (parens free).
//   5. MODERATE DENSITY — a line never carries more than 5 word tiles
//      (the longest sentence shape is 5 words; a 12-row single-column
//      page must stay uncrowded).
//   6. CHUNKER PASS-THROUGH — generateDocument's page chunking keeps the
//      tile metadata on the printed Problems (document.ts spreads
//      `...item`; PrintableSheet renders from the chunked page).
//   7. DETERMINISM — a double generation is byte-identical.

import { describe, it, expect } from 'vitest';
import { seedFrom, getEnglishGradeConfig, generateSheet, generateDocument, type GradeConfig } from '../../framework';
import { lettersSpec, sentenceSpec } from './pins';

// Same seed the framework uses (see the per-plugin test files).
function sheet(spec: { id: string }, grade: GradeConfig) {
    return generateSheet(spec as never, grade, seedFrom([grade.id, spec.id, 0]));
}

const g = (id: number) => getEnglishGradeConfig(id);

describe('tile scaffolds — Alphabet Order write-boxes (letters, Y1–Y3 only)', () => {
    it('Y1–Y3 box EVERY sequence blank and ONLY sequence blanks (exact pinned counts)', () => {
        // Exact count of write-boxed rows on the pinned page-1 sheet, per
        // year (regenerated by scripts/generate-pins.ts -> eng-pins.json).
        // A change here means a word/shape-bank or kind change: deliberate.
        // T5E re-pin: 8 rows/page (was 24); the boxed counts follow the
        // page-1 deck draw of sequence prompts for the pinned seed.
        const pinnedBoxed: Record<number, number> = { 1: 3, 2: 4, 3: 3 };
        for (const gradeId of [1, 2, 3]) {
            const rows = sheet(lettersSpec, g(gradeId));
            expect(rows.length).toBe(8);
            const boxed = rows.filter((p) => p.tileBlanks === 'letter');
            // (1+2) Exact pin + every boxed prompt is a sequence prompt.
            expect(boxed.length).toBe(pinnedBoxed[gradeId]);
            // (3) Each sequence prompt has exactly ONE "__" — the write-box
            //     is the single answer slot. Mixed rows (boxed but multi-
            //     blank, or unboxed but blank-bearing) would break either
            //     half of this exact split.
            expect(boxed.every((p) => (p.prompt.match(/__/g) || []).length === 1)).toBe(true);
            expect(rows.filter((p) => p.prompt.includes('__')).length).toBe(boxed.length);
            // Letters rows never carry the word-tile metadata (sentences only).
            expect(rows.every((p) => p.tileWords === undefined)).toBe(true);
        }
    });

    it('Prep and Years 4..6 print NO write-boxes (legacy underlines unchanged)', () => {
        for (const gradeId of [0, 4, 5, 6]) {
            const rows = sheet(lettersSpec, g(gradeId));
            if (rows.length === 0) continue; // not offered
            // (1) Outside the band: no tile metadata at all — the printed
            //     row keeps its plain underline blanks.
            expect(rows.every((p) => p.tileBlanks === undefined && p.tileWords === undefined)).toBe(true);
        }
    });
});

describe('tile scaffolds — Sentence Building word tiles (Y1–Y3 only)', () => {
    // T5E two-format contract (see SentenceBuildingWorksheet.ts): early-band
    // pages mix FORMAT 1 "Put the words in the correct order" rows (word
    // tiles + write-boxes, bank never printed as text) with FORMAT 2 reorder
    // MCQ rows (three candidate orders printed inside the prompt, no tiles).
    // Every FORMAT 1 row is scaffolded; MCQ rows carry no tile metadata and
    // are recognised by their stem. Outside the band no row carries tiles.
    const MCQ_STEM = 'Which sentence is in the correct order?';
    it('every Y1–3 row carries word write-boxes + the scrambled bank as tiles (no answer leakage)', () => {
        for (const gradeId of [1, 2, 3]) {
            const rows = sheet(sentenceSpec, g(gradeId));
            expect(rows.length).toBe(4);
            for (const p of rows) {
                if (p.prompt.startsWith(MCQ_STEM)) {
                    // Format 2 — MCQ: options live in the prompt, no tiles.
                    expect(p.tileBlanks).toBeUndefined();
                    expect(p.tileWords).toBeUndefined();
                    expect(p.prompt.includes('(')).toBe(true);
                    continue;
                }
                // (1) Inside the band: every Format-1 row is scaffolded.
                expect(p.tileBlanks).toBe('word');
                expect(Array.isArray(p.tileWords)).toBe(true);
                // Blanks and tiles line up one-for-one: the generator prints
                // ONE blank per word UNIT ("__"), and the unit may be two
                // words ("The frog") — so the tile count equals the blank
                // count, NOT the answer's raw whitespace-split count. (The
                // unit composition is pinned by the character-multiset fold
                // below.)
                const blanks = (p.prompt.match(/__/g) || []).length;
                expect(p.tileWords.length).toBe(blanks);
                // (5) Moderate density: at most 5 word tiles per line.
                expect(p.tileWords.length).toBeLessThanOrEqual(5);
                // (4a) The early prompt no longer prints the bank as text.
                expect(p.prompt.includes('(')).toBe(false);
                // (4b) The tiles are the SHOWN order — never the answer
                //      order (words.ts shuffleWords has an identity guard
                //      that re-shuffles a no-op scramble).
                expect(p.tileWords.join(' ')).not.toBe(p.answer);
                // (4c) The tiles are still a permutation of the answer:
                //      fold both sides to a sorted character multiset (the
                //      word units may contain spaces, e.g. "The frog").
                const fold = (s: string) => [...s.replace(/ /g, '')].sort().join('');
                expect(fold(p.tileWords.join(' '))).toBe(fold(p.answer));
            }
        }
    });

    it('pins the exact page-1 tile counts and max bank size per year', () => {
        // page-1 sampling outcome for the pinned seed: [tiled rows, max tiles
        // on a line]. The STRUCTURAL bound is 5 (longest shape); the per-year
        // value is what the pinned seed actually prints (a Y1 page-1 sample
        // happens to top out at 3-word lines). Re-pin on deliberate change.
        // T5E re-pin (4 rows/page, mixed formats): the pinned seed draws 4
        // Format-1 tile rows at Y1 and 1 at Y2/Y3 (the rest are reorder MCQ).
        const pinned: Record<number, [number, number]> = { 1: [4, 2], 2: [1, 3], 3: [1, 3] };
        for (const gradeId of [1, 2, 3]) {
            const rows = sheet(sentenceSpec, g(gradeId));
            const tiled = rows.filter((p) => Array.isArray(p.tileWords));
            expect(tiled.length).toBe(pinned[gradeId][0]);
            const max = Math.max(...tiled.map((p) => p.tileWords!.length));
            expect(max).toBe(pinned[gradeId][1]);
        }
    });

    it('Years 4..6 keep the legacy parenthesised prompt and no tile metadata', () => {
        for (const gradeId of [4, 5, 6]) {
            const rows = sheet(sentenceSpec, g(gradeId));
            expect(rows.length).toBe(4);
            for (const p of rows) {
                // (1) Outside the band: zero tile metadata; the scrambled
                //     bank stays in the prompt text (legacy byte-stable).
                expect(p.tileBlanks).toBeUndefined();
                expect(p.tileWords).toBeUndefined();
                expect(p.prompt.includes('(')).toBe(true);
            }
        }
    });

    it('Prep offers no sentence sheet (unoffered type => empty)', () => {
        expect(sheet(sentenceSpec, g(0))).toEqual([]);
    });
});

describe('tile scaffolds — chunker pass-through + determinism', () => {
    it('generateDocument keeps tile metadata on the printed Problems', () => {
        // The document chunker (document.ts) maps RawProblem -> Problem by
        // spreading `...item`; a regression that dropped the tile fields
        // here would print plain underlines despite the generator scaffolds.
        const doc = generateDocument(sentenceSpec, g(2), seedFrom([2, 'sentence', 0]), 2);
        expect(doc.pages).toHaveLength(2);
        const [page1, page2] = doc.pages;
        expect(page1.length).toBe(4);
        expect(page2.length).toBe(4);
        // T5E two-format contract: tile metadata survives chunking on every
        // Format-1 row (prompt + tiles together identify the printed row).
        const tiled = [...page1, ...page2].filter((p) => p.prompt.startsWith('Put the words'));
        expect(tiled.length).toBeGreaterThan(0);
        for (const p of tiled) {
            expect(p.tileBlanks).toBe('word');
            expect(Array.isArray(p.tileWords)).toBe(true);
        }
        // The chunked page 1 is exactly the pinned sheet (identity).
        expect(doc.pages[0]).toEqual(sheet(sentenceSpec, g(2)));
    });

    it('a double generation is byte-identical (tile metadata included)', () => {
        for (const [spec, gradeId] of [[lettersSpec, 1], [sentenceSpec, 2]] as const) {
            const a = JSON.stringify(sheet(spec, g(gradeId)));
            const b = JSON.stringify(sheet(spec, g(gradeId)));
            expect(a).toBe(b);
        }
    });
});
